"""Unit I: Python interview scenarios."""

from __future__ import annotations

from app.services.python_practice.content.build import mcq as M, out as O


def questions() -> list[dict]:
    return [
        O("unexpected-results", "medium", "Why does this print [1, 2] instead of [2]? Predict the output.", "def add(x, acc=[]):\n    acc.append(x)\n    return acc\n\nadd(1)\nprint(add(2))", "[1, 2]", ["[2]", "[1]", "[]"], "The default list is created once at definition time and reused across calls.", fmt="scenario"),
        O("unexpected-results", "hard", "A developer expects 3 lines of output. What is actually printed?", "funcs = []\nfor i in range(3):\n    funcs.append(lambda: print(i))\nfor f in funcs:\n    f()", "2\n2\n2", ["0\n1\n2", "3\n3\n3", "0\n0\n0"], "Each lambda looks up i when called, after the loop finished with i == 2. Bind it: lambda i=i: print(i).", fmt="scenario"),
        M("choosing-collections", "medium", "You must store a fixed (latitude, longitude) pair as a dictionary key. Which type?", "tuple", ["list", "set", "dict"], "Keys must be hashable; tuples of numbers are hashable and immutable, lists are not.", fmt="scenario"),
        M("choosing-collections", "medium", "You need to keep insertion order, look up by key in O(1) and update counts. Which structure?", "dict (or collections.Counter)", ["list of tuples", "set", "tuple"], "Dicts preserve insertion order (3.7+) and provide O(1) average lookups and updates.", fmt="scenario", py="3.7+"),
        M("debugging-function", "medium", "average([]) crashes with ZeroDivisionError. What is the best first step when debugging?", "Reproduce with the smallest failing input, read the traceback, and decide the intended behaviour for empty input", ["Wrap the function in try/except: pass", "Rewrite the whole module", "Remove the test"], "A minimal reproduction and a clear specification of expected behaviour come before any change.", fmt="scenario"),
        O("debugging-function", "medium", "This function should return the largest even number or None. What does it return for [3, 8, 5]?", "def largest_even(a):\n    best = 0\n    for n in a:\n        if n % 2 == 0 and n > best:\n            best = n\n    return best\n\nprint(largest_even([3, 8, 5]), largest_even([1, 3]), largest_even([-4, -2]))", "8 0 0", ["8 None None", "8 None -2", "8 0 -2"], "Starting from 0 makes 'no even number' and negative evens return 0, which is wrong. Start from None and handle it explicitly.", fmt="scenario"),
        M("improving-code", "medium", "This loop checks `if x in big_list` for each of 100,000 items. What is the simplest big improvement?", "Convert big_list to a set once before the loop", ["Use a while loop instead of for", "Sort big_list inside the loop", "Use recursion"], "List membership is O(n) per check; set membership is average O(1), turning O(n*m) into O(n+m).", fmt="scenario"),
        O("improving-code", "medium", "Both versions return the same result. Which is faster for large n, and what is printed here?", "def slow(a): return [x for x in a if a.count(x) == 1]\ndef fast(a):\n    from collections import Counter\n    c = Counter(a)\n    return [x for x in a if c[x] == 1]\n\nd = [1, 2, 2, 3]\nprint(slow(d) == fast(d), fast(d))", "True [1, 3]", ["False [1, 3]", "True [2]", "True [1, 2, 2, 3]"], "slow is O(n^2) because count scans the list for each element; fast is O(n) with one Counter pass.", fmt="scenario"),
        O("malformed-input", "medium", "What is printed?", "def parse_age(s):\n    try:\n        n = int(s.strip())\n    except (ValueError, AttributeError):\n        return None\n    return n if 0 <= n <= 150 else None\n\nprint([parse_age(x) for x in ['42', ' 7 ', 'abc', '', '-1', '999', None]])", "[42, 7, None, None, None, None, None]", ["[42, 7, None, None, -1, 999, None]", "[42, 7, 0, 0, None, None, 0]", "ValueError"], "Parse defensively: strip, convert, range-check, and return one defined value for every bad input.", fmt="scenario"),
        M("malformed-input", "medium", "A CSV has a few rows with the wrong number of columns. What does a robust loader do?", "Validate each row, collect or log the bad rows with line numbers, and keep processing the good ones", ["Stop at the first bad row without telling anyone", "Pad every row with random data", "Ignore the header"], "Bad data is normal; report it so it can be fixed, and don't lose the good records.", fmt="scenario"),
        M("reusable-modules", "medium", "Which structure makes a script importable without running its main logic on import?", "Put the logic in functions and guard the entry point with if __name__ == '__main__':", ["Put everything at module level", "Rename the file to main.txt", "Call sys.exit() at the top"], "The guard lets other modules (and tests) import the functions safely.", fmt="scenario"),
        M("reusable-modules", "medium", "Which is a hallmark of a well-designed reusable module?", "A small, documented public API with no hidden global state or side effects at import", ["It reads input() at import time", "It edits sys.path to find files", "It uses global variables for all state"], "Explicit parameters and return values make code reusable and testable.", fmt="scenario"),
        M("testable-code", "medium", "Which function is easiest to unit test?", "A pure function that takes inputs and returns a value", ["One that reads input(), prints results and changes globals", "One that opens a hard-coded file path", "One that depends on the current time without a parameter"], "Separate computation from I/O and inject dependencies (files, clocks) so tests can control them.", fmt="scenario"),
        O("testable-code", "medium", "What is printed?", "import io\ndef count_lines(f):\n    return sum(1 for _ in f)\n\nprint(count_lines(io.StringIO('a\\nb\\nc\\n')))", "3", ["2", "1", "TypeError"], "Accepting a file-like object (instead of a path) lets tests pass an in-memory StringIO.", fmt="scenario"),
        M("large-files", "medium", "A 20 GB log must be scanned for a pattern. Which approach is right?", "Iterate line by line (or in fixed-size chunks) and keep only counters or matches in memory", ["Read it all with f.read()", "Use f.readlines()", "Copy it into a list first"], "Streaming keeps memory constant regardless of file size.", fmt="scenario"),
        O("large-files", "medium", "What is printed?", "import io\nf = io.StringIO('a\\nb\\nc\\nd\\n')\nfirst = next(f).strip()\nrest = sum(1 for _ in f)\nprint(first, rest)", "a 3", ["a 4", "a 0", "b 3"], "A file is a one-pass iterator: next() consumes line one, and the loop counts the remaining three.", fmt="scenario"),
        M("resource-leaks", "medium", "Which code guarantees the file is closed even if processing raises?", "with open(path) as f: process(f)", ["f = open(path); process(f); f.close()", "f = open(path); process(f)", "open(path); process(path)"], "A with block closes the resource in all cases; plain close() is skipped when an exception occurs first.", fmt="scenario"),
        O("resource-leaks", "hard", "What is printed?", "class R:\n    log = []\n    def __enter__(self): R.log.append('in'); return self\n    def __exit__(self, *a): R.log.append('out')\n\ntry:\n    with R():\n        raise RuntimeError\nexcept RuntimeError:\n    pass\nprint(R.log)", "['in', 'out']", ["['in']", "['out']", "[]"], "The context manager always runs cleanup, even when the body raises.", fmt="scenario"),
        M("concurrency-limits", "medium", "Your CPU-bound Python function is run in 8 threads but is no faster than one thread. Why?", "In standard CPython the GIL lets one thread run Python bytecode at a time; use multiprocessing or native extensions", ["Threads are disabled on this computer", "Python limits programs to one function", "The list is too long"], "Threads help I/O-bound work. For CPU-bound work use processes (or the experimental free-threaded 3.13 build).", fmt="scenario", py="3.12 and 3.13"),
        M("concurrency-limits", "medium", "Two threads do counter += 1 on a shared int without a lock. What can happen?", "Lost updates: the read-modify-write is not atomic, so the final count can be too low", ["Python raises an error immediately", "The GIL makes it always correct", "The counter becomes a string"], "The GIL protects interpreter internals, not your multi-step operations. Use a lock or a queue.", fmt="scenario"),
        M("explaining-code", "easy", "An interviewer asks you to explain `[x for x in data if x > 0]`. Which explanation is best?", "'It builds a new list containing each item of data that is greater than zero, in the original order.'", ["'It is a list.'", "'It uses the for keyword.'", "'It is Pythonic.'"], "Say what the code does, what it returns and any assumptions, in plain terms.", fmt="scenario"),
        O("explaining-code", "medium", "Explain-then-predict: what does this print, and why? (The reason matters in an interview.)", "a = [1, 2, 3]\nb = a\nb += [4]\nc = a + [5]\nprint(a, c)", "[1, 2, 3, 4] [1, 2, 3, 4, 5]", ["[1, 2, 3] [1, 2, 3, 4, 5]", "[1, 2, 3, 4] [1, 2, 3, 5]", "[1, 2, 3] [1, 2, 3, 5]"], "`b += [4]` extends the shared list in place, so a changes; `a + [5]` makes a new list.", fmt="scenario"),
        M("tradeoffs", "medium", "Sorting a list then binary searching once, versus a single linear scan. Which is better for ONE lookup?", "The linear scan: O(n) beats sorting's O(n log n); sorting pays off only for many lookups", ["Sorting first, always", "Neither works", "Both are O(1)"], "Choose by workload: amortise the sort over many queries or just scan once.", fmt="scenario"),
        M("tradeoffs", "hard", "Compare a list and a deque used as a queue. Which statement is correct?", "deque.popleft() is O(1) while list.pop(0) is O(n), but a list supports O(1) indexing in the middle", ["They are identical in every operation", "A list is always faster", "A deque cannot be iterated"], "Pick the structure whose fast operations match your access pattern.", fmt="scenario"),
    ]
